//! Project Compilation and Dependency Validation Matrix.
//!
//! Ensures that every project generated by the IDE has the correct and complete
//! list of dependencies to compile without errors, across both engines (Makepad and egui),
//! with and without data binding, and with third-party components.

use crawrad_codegen::AlvoGerador;
use crawrad_codegen::dependencias::{Dependencia, dependencias_do_projeto};
use std::path::{Path, PathBuf};
use std::process::Command;

#[test]
fn makepad_matrix_without_binding_has_widgets_and_runtime() {
    let deps = dependencias_do_projeto(AlvoGerador::Makepad, true, false);
    let nomes: Vec<&str> = deps.iter().map(|d| d.nome()).collect();
    assert!(
        nomes.contains(&"makepad-widgets"),
        "Makepad with form must include makepad-widgets"
    );
    assert!(
        nomes.contains(&"crawrad-runtime"),
        "Makepad with form must include crawrad-runtime because form.rs has `use crawrad_runtime::prelude::*;`"
    );
    assert!(
        nomes.contains(&"crawrad-runtime-makepad"),
        "Makepad with form must include crawrad-runtime-makepad for native adapters"
    );
    assert!(
        !nomes.contains(&"crawrad-binding"),
        "Makepad without data binding must not include crawrad-binding"
    );

    // Validates that crawrad-runtime and crawrad-runtime-makepad are referenced via local path
    let runtime_dep = deps.iter().find(|d| d.nome() == "crawrad-runtime").unwrap();
    assert!(
        matches!(runtime_dep, Dependencia::Caminho { .. }),
        "crawrad-runtime must be referenced as Dependencia::Caminho in bridge phase"
    );
    let runtime_makepad_dep = deps
        .iter()
        .find(|d| d.nome() == "crawrad-runtime-makepad")
        .unwrap();
    assert!(
        matches!(runtime_makepad_dep, Dependencia::Caminho { .. }),
        "crawrad-runtime-makepad must be referenced as Dependencia::Caminho in bridge phase"
    );
}

#[test]
fn makepad_matrix_with_binding_has_widgets_runtime_and_binding() {
    let deps = dependencias_do_projeto(AlvoGerador::Makepad, true, true);
    let nomes: Vec<&str> = deps.iter().map(|d| d.nome()).collect();
    assert!(nomes.contains(&"makepad-widgets"));
    assert!(nomes.contains(&"crawrad-runtime"));
    assert!(nomes.contains(&"crawrad-runtime-makepad"));
    assert!(
        nomes.contains(&"crawrad-binding"),
        "Makepad with data binding must include crawrad-binding"
    );

    let binding_dep = deps.iter().find(|d| d.nome() == "crawrad-binding").unwrap();
    assert!(matches!(binding_dep, Dependencia::Caminho { .. }));
}

#[test]
fn egui_matrix_without_binding_has_eframe_and_runtime() {
    let deps = dependencias_do_projeto(AlvoGerador::Egui, true, false);
    let nomes: Vec<&str> = deps.iter().map(|d| d.nome()).collect();
    assert!(nomes.contains(&"eframe"));
    assert!(
        nomes.contains(&"crawrad-runtime"),
        "the generated egui code calls crawrad_runtime::file_dialog (#567)"
    );
    assert!(!nomes.contains(&"crawrad-runtime-makepad"));
    assert!(!nomes.contains(&"crawrad-binding"));
}

#[test]
fn egui_matrix_with_binding_has_eframe_and_binding() {
    let deps = dependencias_do_projeto(AlvoGerador::Egui, true, true);
    let nomes: Vec<&str> = deps.iter().map(|d| d.nome()).collect();
    assert!(nomes.contains(&"eframe"));
    assert!(nomes.contains(&"crawrad-binding"));
}

#[test]
fn creation_adds_all_dependencies_from_single_list() {
    // Proves that cargo add arguments are generated properly for each dependency in the matrix
    let deps = dependencias_do_projeto(AlvoGerador::Makepad, true, true);
    for dep in deps {
        let args = dep.args_cargo_add();
        assert!(
            !args.is_empty(),
            "Each dependency must produce cargo add arguments"
        );
        if let Dependencia::Caminho { path, .. } = &dep {
            assert!(
                path.exists(),
                "Local crate path must exist on disk: {:?}",
                path
            );
        }
    }
}

// ---------------------------------------------------------------------------
// HEAVY REAL COMPILATION TESTS OF THE MATRIX (Item 3)
// ---------------------------------------------------------------------------

fn get_workspace_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(|p| p.parent())
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| PathBuf::from("."))
}

fn get_shared_matriz_target_dir() -> PathBuf {
    get_workspace_root()
        .join("target")
        .join("test_matriz_target")
}

fn compilar_projeto_criado(dir: &Path) {
    let target_dir = get_shared_matriz_target_dir();
    let saida = Command::new(env!("CARGO"))
        .arg("build")
        .env("CARGO_TARGET_DIR", &target_dir)
        .env_remove("RUSTFLAGS")
        .current_dir(dir)
        .output()
        .expect("run cargo build on the project created by the IDE");

    assert!(
        saida.status.success(),
        "The project created by the IDE failed to compile (`cargo build`):\nSTDOUT:\n{}\nSTDERR:\n{}",
        String::from_utf8_lossy(&saida.stdout),
        String::from_utf8_lossy(&saida.stderr)
    );
}

fn testar_caso_matriz(alvo: AlvoGerador, usa_binding: bool, com_terceiro: bool, tag: &str) {
    let temp_root = std::env::temp_dir().join(format!(
        "crawrad_matriz_{}_{:?}_{}",
        std::process::id(),
        alvo,
        tag
    ));
    if temp_root.exists() {
        let _ = std::fs::remove_dir_all(&temp_root);
    }
    std::fs::create_dir_all(&temp_root).expect("create temporary folder");

    let mut extras = Vec::new();
    if com_terceiro {
        extras.push(Dependencia::caminho(
            "gauge-crawrad",
            get_workspace_root()
                .join("components")
                .join("gauge-crawrad"),
        ));
    }

    let opcoes = crawrad_project::project_template::ProjectTemplateOptions {
        framework: alvo,
        use_binding: usa_binding,
        extra_dependencies: extras,
    };

    let res = crawrad_project::project_template::create_project_template_with_options(
        &temp_root, "app", "gui_app", false, opcoes,
    );
    assert!(
        res.is_ok(),
        "create_project_template_with_options failed: {:?}",
        res.err()
    );
    let raiz = res.unwrap();

    compilar_projeto_criado(&raiz);
    let _ = std::fs::remove_dir_all(&temp_root);
}

#[test]
#[ignore = "compiles real makepad project; use --ignored"]
fn makepad_compilation_matrix_without_binding() {
    testar_caso_matriz(AlvoGerador::Makepad, false, false, "sem_binding");
}

#[test]
#[ignore = "compiles real makepad project; use --ignored"]
fn makepad_compilation_matrix_with_binding() {
    testar_caso_matriz(AlvoGerador::Makepad, true, false, "com_binding");
}

